import { LOGO } from "./logo-paths";

/**
 * RedShadow eclipse wordmark (outlines from the redshadow-logo kit, generated by logo-src/build_brand.py).
 * The O carries the red eclipse cut; the rest follows currentColor so it works on light and dark grounds.
 */
export function Logo({ height = 28, className = "" }: { height?: number; className?: string }) {
  const width = (LOGO.W / LOGO.H) * height;
  return (
    <svg role="img" aria-label="RedShadow" viewBox={LOGO.viewBox} width={width} height={height} className={className}>
      <path d={LOGO.wedge} fill={LOGO.CRIMSON} />
      <path d={LOGO.ink} fill="currentColor" />
    </svg>
  );
}

/** Square mark (the eclipse O on the app tile) for the collapsed rail. */
export function Mark({ size = 36 }: { size?: number }) {
  return <img src="/favicon.svg" width={size} height={size} alt="RedShadow" />;
}
